iv class=\"row g-2 small\">\r\n            <div class=\"col-md-6\"><i class=\"fas fa-file-lines me-2 text-primary\"></i>{{ selectedTemplate.label }}</div>\r\n            <div class=\"col-md-6\"><i class=\"fas fa-hashtag me-2 text-primary\"></i>{{ selectedTemplate.itemCount }} item &middot; lingua {{ selectedTemplate.language || 'it' }}</div>\r\n            <div class=\"col-md-6\">\r\n              <i class=\"fas fa-user me-2 text-primary\"></i>\r\n              {{ selectedPatient ? selectedPatient.firstName + ' ' + selectedPatient.lastName : 'Nessun paziente selezionato' }}\r\n            </div>\r\n            <div class=\"col-md-6\">\r\n              <i class=\"fas fa-clipboard-list me-2 text-primary\"></i>\r\n              {{ selectedCompileType ? selectedCompileType.descType : 'Tipo non specificato' }}\r\n            </div>\r\n            <div class=\"col-md-6\"><i class=\"fas fa-user-tie me-2 text-primary\"></i>{{ downloadForm.get('interviewer')?.value || 'Intervistatore non specificato' }}</div>\r\n            <div class=\"col-md-6\"><i class=\"fas fa-calendar me-2 text-primary\"></i>{{ (assessmentDate | date:'dd/MM/yyyy') || 'Data non specificata' }}</div>\r\n          </div>\r\n          <div class=\"small text-muted mt-3\"><i class=\"fas fa-file me-2\"></i>File generato: {{ filename }}</div>\r\n        </div>\r\n      </div>\r\n    }\r\n  </form>\r\n\r\n  <div class=\"d-flex justify-content-end gap-2 mb-4\">\r\n    <button class=\"btn btn-outline-primary\" type=\"button\" (click)=\"onPreview()\" [disabled]=\"isPreviewing || !selectedTemplate\">\r\n      @if (isPreviewing) {\r\n        <span class=\"spinner-border spinner-border-sm me-2\" role=\"status\"></span>\r\n      } @else {\r\n        <i class=\"fas fa-print me-2\"></i>\r\n      }\r\n      Anteprima / Stampa\r\n    </button>\r\n    <button class=\"btn btn-primary\" type=\"button\" (click)=\"onDownload()\" [disabled]=\"isDownloading || !selectedTemplate\">\r\n      @if (isDownloading) {\r\n        <span class=\"spinner-border spinner-border-sm me-2\" role=\"status\"></span>\r\n      } @else {\r\n        <i class=\"fas fa-download me-2\"></i>\r\n      }\r\n      Scarica PDF\r\n    </button>\r\n  </div>\r\n</div>\r\n",
